%script
EXEC DBMS_CLOUD_AI.SET_PROFILE('genai');
BEGIN
  DBMS_CLOUD_AI.SET_ATTRIBUTE(profile_name => 'genai', attribute_name => 'object_list', attribute_value => '[{"owner": "' || USER || '", "name": "SLED_SERVICE_REQUESTS_V"},{"owner": "' || USER || '", "name": "AGENT_ACTIONS"}]');
END;
/

%script
BEGIN
  EXECUTE IMMEDIATE q'[CREATE TABLE agent_actions (action_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, agent_name VARCHAR2(128) NOT NULL, action_type VARCHAR2(128) NOT NULL, entity_type VARCHAR2(128) NOT NULL, entity_id NUMBER NOT NULL, decision_payload VARCHAR2(4000), confidence NUMBER, execution_status VARCHAR2(40) NOT NULL, executed_at TIMESTAMP NOT NULL)]';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 THEN RAISE; END IF; END;
/
CREATE OR REPLACE FUNCTION state_local_get_priority_request RETURN VARCHAR2 AS v_result VARCHAR2(4000); BEGIN
 SELECT 'service_request_id='||service_request_id||'; region='||service_region_code||'; status='||request_status||'; urgency_score='||urgency_score||'; recommended_action=Create simulated planning review' INTO v_result FROM sled_service_requests_v ORDER BY urgency_score DESC, service_value_exposure DESC, service_request_id FETCH FIRST 1 ROW ONLY; RETURN v_result;
EXCEPTION WHEN NO_DATA_FOUND THEN RETURN 'NO_SERVICE_REQUEST_FOUND'; END;
/
CREATE OR REPLACE FUNCTION state_local_record_planning_review RETURN VARCHAR2 AS PRAGMA AUTONOMOUS_TRANSACTION; v_id NUMBER; v_score NUMBER; v_count NUMBER; v_action NUMBER; BEGIN
 SELECT service_request_id, urgency_score INTO v_id, v_score FROM sled_service_requests_v ORDER BY urgency_score DESC, service_value_exposure DESC, service_request_id FETCH FIRST 1 ROW ONLY;
 SELECT COUNT(*) INTO v_count FROM agent_actions WHERE agent_name='STATE_LOCAL_SERVICE_AGENT' AND action_type='PLANNING_REVIEW' AND entity_type='SERVICE_REQUEST' AND entity_id=v_id;
 IF v_count>0 THEN RETURN 'PLANNING_REVIEW_ALREADY_EXISTS; service_request_id='||v_id; END IF;
 INSERT INTO agent_actions(agent_name,action_type,entity_type,entity_id,decision_payload,confidence,execution_status,executed_at) VALUES('STATE_LOCAL_SERVICE_AGENT','PLANNING_REVIEW','SERVICE_REQUEST',v_id,'Simulated planning review; urgency_score='||v_score,0.950,'completed',SYSTIMESTAMP) RETURNING action_id INTO v_action; COMMIT; RETURN 'PLANNING_REVIEW_CREATED; action_id='||v_action||'; service_request_id='||v_id;
EXCEPTION WHEN NO_DATA_FOUND THEN RETURN 'NO_SERVICE_REQUEST_FOUND'; WHEN OTHERS THEN ROLLBACK; RAISE; END;
/
SELECT object_name,status FROM user_objects WHERE object_name IN ('AGENT_ACTIONS','STATE_LOCAL_GET_PRIORITY_REQUEST','STATE_LOCAL_RECORD_PLANNING_REVIEW') ORDER BY object_name;

