%script
BEGIN
  DBMS_CLOUD_AI_AGENT.CREATE_TOOL(
    tool_name   => 'STATE_LOCAL_LOOKUP_TOOL',
    attributes  => '{"instruction":"Retrieve the highest-urgency service request. This tool is read-only and has no parameters.","function":"state_local_get_priority_request"}',
    description => 'Returns approved service-request evidence'
  );

  DBMS_CLOUD_AI_AGENT.CREATE_TOOL(
    tool_name   => 'STATE_LOCAL_REVIEW_TOOL',
    attributes  => '{"instruction":"Create at most one simulated planning-review audit row for the retrieved request. Never change source service data or trigger an external workflow.","function":"state_local_record_planning_review"}',
    description => 'Creates one constrained simulated audit row'
  );

  DBMS_CLOUD_AI_AGENT.CREATE_AGENT(
    agent_name  => 'STATE_LOCAL_SERVICE_AGENT',
    attributes  => '{"profile_name":"genai","role":"Use only supplied tools. Retrieve evidence first. You may create one simulated planning-review audit row only. Never change source service, resident, capacity, or route data and never trigger external workflows."}',
    description => 'Constrained service-planning agent'
  );

  DBMS_CLOUD_AI_AGENT.CREATE_TASK(
    task_name   => 'STATE_LOCAL_SERVICE_TASK',
    attributes  => '{"instruction":"Call STATE_LOCAL_LOOKUP_TOOL, report its exact result, then call STATE_LOCAL_REVIEW_TOOL and report its exact result. User request: {query}","tools":["STATE_LOCAL_LOOKUP_TOOL","STATE_LOCAL_REVIEW_TOOL"]}',
    description => 'Controlled planning-review task'
  );

  DBMS_CLOUD_AI_AGENT.CREATE_TEAM(
    team_name   => 'STATE_LOCAL_SERVICE_TEAM',
    attributes  => '{"agents":[{"name":"STATE_LOCAL_SERVICE_AGENT","task":"STATE_LOCAL_SERVICE_TASK"}],"process":"sequential"}',
    description => 'Constrained service-planning team'
  );
END;
/

%script
SELECT 'TOOL' object_type,tool_name object_name,status FROM user_ai_agent_tools WHERE tool_name LIKE 'STATE_LOCAL_%' UNION ALL SELECT 'AGENT',agent_name,status FROM user_ai_agents WHERE agent_name='STATE_LOCAL_SERVICE_AGENT' UNION ALL SELECT 'TASK',task_name,status FROM user_ai_agent_tasks WHERE task_name='STATE_LOCAL_SERVICE_TASK' UNION ALL SELECT 'TEAM',agent_team_name,status FROM user_ai_agent_teams WHERE agent_team_name='STATE_LOCAL_SERVICE_TEAM';
EXEC DBMS_CLOUD_AI_AGENT.SET_TEAM('STATE_LOCAL_SERVICE_TEAM');
SELECT AI AGENT Review the current highest-urgency service request and report the exact tool results;
SELECT action_id,action_type,entity_type,entity_id,execution_status,executed_at FROM agent_actions WHERE agent_name='STATE_LOCAL_SERVICE_AGENT' ORDER BY action_id DESC;
SELECT tool_name,start_date,SUBSTR(output,1,120) result FROM user_ai_agent_tool_history WHERE tool_name LIKE 'STATE_LOCAL_%' ORDER BY start_date DESC FETCH FIRST 10 ROWS ONLY;
SELECT team_name,start_date,state FROM user_ai_agent_team_history WHERE team_name='STATE_LOCAL_SERVICE_TEAM' ORDER BY start_date DESC FETCH FIRST 5 ROWS ONLY;
SELECT AI AGENT Review the current highest-urgency service request again and report the exact tool results;
SELECT entity_id,COUNT(*) simulated_review_rows FROM agent_actions WHERE agent_name='STATE_LOCAL_SERVICE_AGENT' GROUP BY entity_id;
